// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// No additional interfaces needed - we're using direct calls

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Determine owner storage slot
        // In Ownable contract: address private _owner; is first variable, so slot 0
        bytes32 ownerSlot = bytes32(uint256(0));

        // Step 2: Overwrite owner storage slot to make attacker the owner
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Step 3: Verify we are now owner
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("owner()"));
        require(success, "owner call failed");
        address currentOwner = abi.decode(data, (address));
        require(currentOwner == attacker, "Failed to become owner");

        // Step 4: Call renounceOwnership() as the new owner
        // We need to use prank to impersonate the attacker (who is now owner)
        vm.prank(attacker);
        (bool renounceSuccess, ) = TARGET.call(abi.encodeWithSignature("renounceOwnership()"));
        require(renounceSuccess, "renounceOwnership failed");

        // Step 5: Verify owner is now address(0)
        (success, data) = TARGET.call(abi.encodeWithSignature("owner()"));
        require(success, "owner call failed after renounce");
        currentOwner = abi.decode(data, (address));
        require(currentOwner == address(0), "Owner not set to zero address");

        // The oracle verification will check that owner == address(0)
        assertEq(currentOwner, address(0), "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
